import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { collectStat, runAgg, runFilter, runHead } from "../src/commands.js";
import { formatCount, prettyJson, renderAgg, renderStat } from "../src/format.js";

// Every transcript on the page runs on demo/access.jsonl, which is generated by
// demo/make-access-log.mjs from a fixed seed and never committed. The numbers
// are therefore a property of that generator: change one entry in its pool of
// paths, statuses or methods and the whole page silently describes a file that
// no longer exists. This test regenerates the log exactly the way the quick
// start does and re-derives each quoted block.

const root = fileURLToPath(new URL("..", import.meta.url));
const readme = readFileSync(join(root, "README.md"), "utf8");

let dir = "";
let accessLog = "";

beforeAll(() => {
  dir = mkdtempSync(join(tmpdir(), "jlb-readme-"));
  accessLog = join(dir, "access.jsonl");
  const made = spawnSync(
    process.execPath,
    [join(root, "demo", "make-access-log.mjs"), "--out", accessLog],
    { encoding: "utf8" },
  );
  if (made.status !== 0) throw new Error(`make-access-log.mjs failed: ${made.stderr}`);
});

afterAll(() => {
  if (dir !== "") rmSync(dir, { recursive: true, force: true });
});

describe("README demo transcripts", () => {
  it("quotes the stat report the generator produces", async () => {
    const stat = await collectStat(accessLog);
    expect(readme).toContain(renderStat(stat, 30));
  });

  it("quotes the first record exactly", async () => {
    const seen: unknown[] = [];
    await runHead(accessLog, 1, { emit: (record) => seen.push(record) });
    expect(seen).toHaveLength(1);
    expect(readme).toContain(prettyJson(seen[0]));
  });

  it("quotes the cost the filtered run reports", async () => {
    const result = await runFilter(accessLog, {
      where: "status>=500 and dur>500",
      limit: 2,
      emit: () => {},
    });
    const footer = `jlb: ${formatCount(result.matched)} matched of ${formatCount(result.scanned)} scanned`;
    expect(readme).toContain(footer);
  });

  it("quotes the grouped tables", async () => {
    const byStatus = await runAgg(accessLog, { by: "status", top: 20 });
    expect(readme).toContain(
      renderAgg(byStatus.groups, {
        by: "status",
        metric: byStatus.metric,
        top: 20,
        truncated: byStatus.groups.length > 20,
        totalGroups: byStatus.totalGroups,
      }),
    );

    const byPath = await runAgg(accessLog, { by: "path", p95: "dur", top: 5 });
    expect(readme).toContain(
      renderAgg(byPath.groups, {
        by: "path",
        metric: byPath.metric,
        top: 5,
        truncated: byPath.totalGroups > 5,
        totalGroups: byPath.totalGroups,
      }),
    );

    const byHost = await runAgg(accessLog, { by: "upstream.host", avg: "dur", top: 20 });
    expect(readme).toContain(
      renderAgg(byHost.groups, {
        by: "upstream.host",
        metric: byHost.metric,
        top: 20,
        truncated: byHost.groups.length > 20,
        totalGroups: byHost.totalGroups,
      }),
    );
  });
});
